MinMaxScaler scaler = MinMaxScaler.builder()
        .featureRange(0.0, 1.0)
        .build();

Matrix scaled = scaler.fitTransform(features);
Matrix restored = scaler.inverseTransform(scaled);

DecisionTree regressor = DecisionTree.builder()
        .task(TreeTask.REGRESSION)
        .maxDepth(6)
        .build();

TreeTask task = regressor.task();

AgglomerativeClustering model = AgglomerativeClustering.builder()
        .clusters(3)
        .linkage(AgglomerativeClustering.Linkage.AVERAGE)
        .build();

model.fit(features);
int[] labels = model.labels();

AgglomerativeClustering model = AgglomerativeClustering.builder()
        .clusters(4)
        .linkage(AgglomerativeClustering.Linkage.SINGLE)
        .build();

AgglomerativeClustering.Linkage used = model.linkage();

FeatureImportance.PermutationResult result = FeatureImportance.permutationImportance(
        model, features, targets, JSL.Metric.ACCURACY, 10, 42L);

int[] order = result.rankedFeaturesDescending();
double top = result.importancesMean()[order[0]];

GaussianMixture gmm = GaussianMixture.builder()
        .components(3)
        .maxIterations(200)
        .tolerance(1e-5)
        .regCovar(1e-6)
        .seed(7L)
        .build();

gmm.fit(features);
double[] labels = gmm.predict(features);
